/**
 * historique.js — ce qui est TERMINÉ, écrit dans le code (étape 5 du plan, 06/10/2026).
 * -----------------------------------------------------------------------
 * Une ligne par fin d'étape, dans l'ordre où elles ont été faites, avec sa
 * date, une ou deux phrases simples sur ce qui a changé et ce qui a été
 * mesuré (tests, durées). La page « Feuille de route » en tire l'état
 * « terminée », la date de fin, « ce qui a changé » et « gain mesuré » de
 * chaque étape, et sa ligne « Tests : N réussis ».
 *
 * Pourquoi dans le CODE et pas dans data/runtime : les données d'exécution du
 * bac à sable ne sont jamais recopiées vers l'appli de Pierre, le code l'est
 * (sandbox-apply). Une ligne écrite ici voyage donc avec l'étape qu'elle
 * raconte. Seules les notes de Pierre sont des données d'exécution
 * (repositories/roadmapRepository.js).
 *
 * À LA FIN D'UNE ÉTAPE (règle « terminé » du plan) :
 *   1. ajouter UNE ligne à HISTORIQUE (sa date de fin, ce qui a changé, ce qui
 *      a été mesuré, le résultat de `npm test` si l'étape l'a passé) ;
 *   2. la retirer de ETAPES_EN_COURS si elle y était ;
 *   3. un complément ou une correction d'une étape déjà finie est une AUTRE
 *      ligne, avec le même `etape` et un `titre` (cf. le complément de la 1).
 * À la fin d'un lot, son bilan (ce qu'on garde, ce qu'on saute, ce qu'on
 * réordonne) s'écrit dans BILANS_DE_LOT.
 *
 * Champs d'une ligne :
 *   etape   l'identifiant du plan (« 4 », « E ») — il doit exister dans plan.js ;
 *   fin     le jour de fin, AAAA-MM-JJ (jour de Paris) ;
 *   heure   l'heure approximative, en texte libre (facultatif) ;
 *   titre   seulement pour un complément ou une correction (facultatif) ;
 *   change  ce qui a changé, en langage simple ;
 *   mesure  ce qui a été mesuré (tests, durées, volumes), ou null ;
 *   tests   { total, reussis, todo, echecs, duree } de `npm test` à ce moment-là
 *           (facultatif ; `todo` = constats « # TODO » non bloquants).
 * -----------------------------------------------------------------------
 */

const ligne = ({ tests = null, ...reste }) => Object.freeze({ heure: null, titre: null, mesure: null, ...reste, tests: tests ? Object.freeze(tests) : null });

